  function compLoad() { if (!LIVEON() || Date.now() - UIcpl.compAt < 60000) return; UIcpl.compAt = Date.now(); api('GET', '/api/cpl/completion').then(x => { UIcpl.comp = x.rows || []; render(); }).catch(() => { }); }
