      <div class="card">${table(['훈련생', '과정', '진도', '누적 학습', '오늘', 'IP 수', '최근 활동', '본인확인', ''], Rw.slice(0, 200).map(r => [esc(r.sid), esc(r.c.name), r.p < (+P.rate || 80) ? tag(r.p + '%', 'r') : pct(r.p), hoursOf(r.secs), hoursOf(r.today), r.ips > 1 ? tag(r.ips + '개', 'y') : String(r.ips || '—'), esc(String(r.last || '—').slice(0, 19).replace('T', ' ')), r.verified ? tag('완료', 'g') : '—', `<button class="btn sm" data-act="cpl-log" data-v="${esc(r.sid)}">학습 로그</button>`]), '훈련생이 없습니다.')}</div>
